// src/components/Book/Book.jsx
import { useState, useCallback, useRef } from 'react';
import { FaChevronLeft, FaChevronRight } from 'react-icons/fa';
import BookCover from './BookCover';
import {
  InfoPage,
  AgrosenseLeft, AgrosenseRight,
  JornadaLeft,   JornadaRight,
  EventsLeft,    EventsRight,
  PixelLeft,     PixelRight,
  VelhaLeft,     VelhaRight,
  PooLeft,       PooRight,
  ContactLeft,   ContactRight,
} from './SpreadContent';
import styles from './Book.module.css';

/* ═══════════════════════════════════════════════════════════
   [EDIT-BOOK] — DADOS EDITÁVEIS
   Comente este bloco + [EDIT-BOOK-STATE] + [EDIT-BOOK-SPREADS]
   ═══════════════════════════════════════════════════════════ */
const INIT = {
  agrosense: {
    id:'agrosense', name:'Agrosense', tagline:'Monitoramento agrícola inteligente',
    tech:'React · Node.js · IoT · MQTT',
    description:'Plataforma de monitoramento agrícola em tempo real com sensores IoT. Coleta dados de temperatura, umidade e solo, exibindo dashboards interativos para tomada de decisão no campo.',
    github:'https://github.com/cgonssalves', imgLeft:null, imgRight:null, video:null,
  },
  jornada: {
    id:'jornada', name:'Jornada Tech', tagline:'Trilhas de aprendizado em tecnologia',
    tech:'React · Firebase · Tailwind CSS',
    description:'Aplicação web para guiar estudantes em trilhas de aprendizado de tecnologia. Sistema de progresso, quizzes e certificados digitais ao concluir cada etapa.',
    github:'https://github.com/cgonssalves', imgLeft:null, imgRight:null, video:null,
  },
  pixel: {
    id:'pixel', name:'UEMG Pixel', tagline:'Canvas colaborativo em tempo real',
    tech:'React · WebSocket · Canvas API',
    description:'Projeto colaborativo onde alunos da UEMG pintam pixels em um canvas compartilhado em tempo real. Inspirado no Reddit Place, promove integração e identidade universitária.',
    github:'https://github.com/cgonssalves', imgLeft:null, imgRight:null, video:null,
  },
  velha: {
    id:'velha', name:'Jogo da Velha Mobile', tagline:'Multiplayer local em React Native',
    tech:'React Native · Expo · AsyncStorage',
    description:'Jogo da velha para Android com modo multiplayer local e contra IA. Animações fluidas com React Native Reanimated e histórico salvo localmente.',
    github:'https://github.com/cgonssalves', imgLeft:null, imgRight:null, video:null,
  },
  poo: {
    id:'poo', name:'POO Visual', tagline:'Visualizador educacional de POO em Java',
    tech:'Java · JavaFX · OOP',
    description:'Ferramenta educacional que visualiza graficamente os conceitos de POO em Java — herança, polimorfismo, encapsulamento e interfaces — de forma interativa e didática.',
    github:'https://github.com/cgonssalves', imgLeft:null, imgRight:null, video:null,
  },
  nasa: {
    id:'nasa', icon:'🚀', title:'NASA Space Apps',
    description:'Hackathon global da NASA realizado em Ituiutaba — MG. Desenvolvimento de soluções para desafios espaciais e ambientais em 48 horas de imersão.',
    tech:'', photos:[],
  },
  maratona: {
    id:'maratona', icon:'💻', title:'Maratona SBC',
    description:'Maratona de Programação da Sociedade Brasileira de Computação. Resolução de problemas algorítmicos em equipe sob pressão de tempo e raciocínio lógico.',
    tech:'', photos:[],
  },
};
/* ════ [EDIT-BOOK] fim ════ */

const CV_B64  = '';
const CV_HREF = `data:application/pdf;base64,${CV_B64}`;

export default function Book() {
  const [spread,   setSpread]   = useState(0);
  const [flipping, setFlipping] = useState(false);
  const [flipDir,  setFlipDir]  = useState(1);   // 1=avançar, -1=voltar
  const bookRef = useRef(null);

  /* ════ [EDIT-BOOK-STATE] ════ */
  const [data, setData] = useState(INIT);
  const handleSave = (id, newData) => setData(d => ({ ...d, [id]: newData }));
  /* ════ [EDIT-BOOK-STATE] fim ════ */

  const isCover = spread === 0;

  // ─── Navegação com animação CSS pura (sem Framer Motion na dobra) ───
  const navigate = useCallback((delta) => {
    if (flipping) return;
    const next = spread + delta;
    if (next < 0 || next > 7) return;

    setFlipDir(delta);
    setFlipping(true);

    // Após a animação CSS terminar (700ms), troca o conteúdo
    setTimeout(() => {
      setSpread(next);
      setFlipping(false);
    }, 700);
  }, [spread, flipping]);

  const goToContact = () => { if (!flipping) navigate(7 - spread); };

  /* ════ [EDIT-BOOK-SPREADS] ════ */
  const SPREADS = {
    0: { lNum:'1', rNum:'2',
      leftEl:  <BookCover onContactClick={goToContact} cvHref={CV_HREF} />,
      rightEl: <InfoPage />,
      isCoverSpread: true,
    },
    1: { lNum:'3', rNum:'4',
      leftEl:  <AgrosenseLeft  p={data.agrosense} onSave={handleSave} />,
      rightEl: <AgrosenseRight p={data.agrosense} onSave={handleSave} />,
    },
    2: { lNum:'5', rNum:'6',
      leftEl:  <JornadaLeft  p={data.jornada} onSave={handleSave} />,
      rightEl: <JornadaRight p={data.jornada} onSave={handleSave} />,
    },
    3: { lNum:'7', rNum:'8',
      leftEl:  <EventsLeft  p={data.nasa}     onSave={handleSave} />,
      rightEl: <EventsRight p={data.maratona} onSave={handleSave} />,
    },
    4: { lNum:'9', rNum:'10',
      leftEl:  <PixelLeft  p={data.pixel} onSave={handleSave} />,
      rightEl: <PixelRight p={data.pixel} onSave={handleSave} />,
    },
    5: { lNum:'11', rNum:'12',
      leftEl:  <VelhaLeft  p={data.velha} onSave={handleSave} />,
      rightEl: <VelhaRight p={data.velha} onSave={handleSave} />,
    },
    6: { lNum:'13', rNum:'14',
      leftEl:  <PooLeft  p={data.poo} onSave={handleSave} />,
      rightEl: <PooRight p={data.poo} onSave={handleSave} />,
    },
    7: { lNum:'15', rNum:'16',
      leftEl:  <ContactLeft />,
      rightEl: <ContactRight />,
    },
  };
  /* ════ [EDIT-BOOK-SPREADS] fim ════ */

  const cur  = SPREADS[spread];
  const prev = spread > 0 ? SPREADS[spread - 1] : null;
  const next = spread < 7 ? SPREADS[spread + 1] : null;

  // Durante o flip para frente:
  //   A página direita ATUAL dobra para a esquerda (flipOut)
  //   A página esquerda do PRÓXIMO spread aparece (flipIn)
  // Durante o flip para trás: invertido

  return (
    <section className={styles.bookSection}>
      <h1 className={styles.siteTitle}>Portfolio <span>Cauã Cavalcante</span></h1>
      <p className={styles.siteSubtitle}>Engenharia de Computação · Full Stack Developer</p>

      <div className={styles.bookWrapper}>
        {/*
          ESTRUTURA DO LIVRO — inspirada no CSS .cover do Turn.js:
          ┌─────────────────────────────────────────────────────┐
          │  spine │ edge │ LEFT page │       RIGHT page        │
          │                           │  .cover (position:abs,  │
          │                           │   width:50%, h:100%,    │
          │                           │   transform-origin:right│
          │                           │   → dobra sobre si)     │
          └─────────────────────────────────────────────────────┘
        */}
        <div className={styles.book} ref={bookRef}>
          <div className={styles.spine} />
          <div className={styles.pagesEdge} />

          {/* ── PÁGINA ESQUERDA (estática) ── */}
          <div className={`${styles.pageLeft} ${cur.isCoverSpread ? styles.pageLeftCover : ''}`}>
            {cur.isCoverSpread
              ? cur.leftEl   /* amber cover */
              : <div className={styles.pageContent}>{cur.leftEl}</div>
            }
            {!cur.isCoverSpread && (
              <span className={styles.pageNum} style={{left:'50%', transform:'translateX(-50%)'}}>
                {cur.lNum}
              </span>
            )}
            {flipping && flipDir > 0 && (
              <div className={styles.flipShadowLeft} />
            )}
          </div>

          {/* ── PÁGINA DIREITA — dobra como um livro real ── */}
          <div className={styles.pageRight}>

            {/* Página de fundo (destino do flip) */}
            <div className={styles.pageContent}>
              {flipping
                ? (flipDir > 0
                    ? (next  ? next.leftEl  : cur.rightEl)   // avançar: mostra LEFT do próximo
                    : (prev  ? prev.rightEl : cur.rightEl))  // voltar:  mostra RIGHT do anterior
                : cur.rightEl
              }
            </div>

            {/*
              .flipPage = a "folha" que vira, igual ao .cover do Turn.js
              position: absolute, width: 50% do container (= página inteira da direita),
              height: 100%, transform-origin: right
              → quando rotateY vai de 0 a -180, ela dobra para a esquerda como papel real
            */}
            <div className={`${styles.flipPage} ${flipping ? (flipDir > 0 ? styles.flipOut : styles.flipIn) : ''}`}>
              <div className={styles.flipFront}>
                {/* Frente da folha = conteúdo atual da direita */}
                <div className={styles.pageContent}>{cur.rightEl}</div>
                <span className={styles.pageNum} style={{right:12}}>{cur.rNum}</span>
              </div>
              <div className={styles.flipBack}>
                {/* Verso da folha = conteúdo esquerdo do próximo spread */}
                <div className={styles.pageContent} style={{transform:'scaleX(-1)'}}>
                  {flipDir > 0
                    ? (next ? next.leftEl : null)
                    : (prev ? prev.rightEl : null)
                  }
                </div>
              </div>
            </div>

            {spread < 7 && !flipping && (
              <div className={styles.cornerFold} onClick={() => navigate(1)} title="Próxima página" />
            )}
            <span className={styles.pageNum} style={{right:12}}>{cur.rNum}</span>
          </div>

          {/* Botões nos cantos inferiores do livro */}
          <button className={`${styles.navBtn} ${styles.navBtnPrev}`}
            onClick={() => navigate(-1)}
            disabled={spread === 0 || flipping}>
            <FaChevronLeft />
          </button>
          <button className={`${styles.navBtn} ${styles.navBtnNext}`}
            onClick={() => navigate(1)}
            disabled={spread === 7 || flipping}>
            <FaChevronRight />
          </button>
        </div>
      </div>
    </section>
  );
}
